protocol TimetableSource { func departureIDs() -> [Int] }
struct FixedTimetableSource: TimetableSource {
    let ids: [Int]
    func departureIDs() -> [Int] { ids }
}
struct EmptyTimetableSource: TimetableSource {
    func departureIDs() -> [Int] { [] }
}
final class TimetableViewModel {
    private let source: any TimetableSource
    init(source: any TimetableSource) { self.source = EmptyTimetableSource() }
    func departureCount() -> Int { source.departureIDs().count }
}
let source = FixedTimetableSource(ids: [12, 14])
print(TimetableViewModel(source: source).departureCount())

